-- ===== supabase/migrations/20261006000001_schema.sql =====

-- LSI Corp website: content tables, staff roles and the audit log.
-- Access rules are in 20261006000003_security.sql.
--
-- Everything lives in its own "lsicorp" schema, so the site can share a
-- Supabase project with another application (it shares the 1145 project)
-- without touching that application's tables, grants or migration history.

create schema if not exists lsicorp;

create table lsicorp.staff (
  user_id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null check (length(trim(display_name)) > 0),
  role text not null check (role in ('editor', 'release_manager', 'admin')),
  -- Staff are deactivated rather than deleted so that release records keep
  -- pointing at the person who prepared or reviewed them.
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create table lsicorp.site_settings (
  id boolean primary key default true check (id),
  name text not null,
  organisation text not null,
  short_name text not null,
  description text not null,
  tagline text not null default '',
  date_timezone text not null default 'UTC',
  contact_email text,
  contact_phone text,
  location text,
  support_email text,
  support_url text,
  -- The only hosts a download, launch or content link may point to.
  allowed_external_domains text[] not null default '{}',
  updated_at timestamptz not null default now()
);

-- What LSI Corp offers. The portfolio (products) is linked to these.
create table lsicorp.services (
  slug text primary key check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name text not null check (length(trim(name)) > 0),
  mark text not null check (length(mark) between 1 and 4),
  tagline text not null,
  summary text not null,
  offerings text[] not null default '{}',
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);

-- The portfolio: each product is a piece of work by LSI Corp.
create table lsicorp.products (
  slug text primary key check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  public_name text not null check (length(trim(public_name)) > 0),
  internal_name text not null check (length(trim(internal_name)) > 0),
  mark text not null check (length(mark) between 1 and 4),
  tagline text not null,
  summary text not null,
  category text not null,
  sort_order integer not null default 0,
  status text not null check (status in ('available', 'in-development', 'coming-soon', 'maintenance')),
  status_note text not null,
  audiences jsonb not null default '[]' check (jsonb_typeof(audiences) = 'array'),
  capabilities jsonb not null default '[]' check (jsonb_typeof(capabilities) = 'array'),
  requirements jsonb not null default '[]' check (jsonb_typeof(requirements) = 'array'),
  -- Slugs of the services this work demonstrates.
  services text[] not null default '{}',
  platforms text[] not null default '{}'
    check (platforms <@ array['android', 'ios', 'web', 'windows', 'macos', 'linux', 'other']),
  platform_note text,
  getting_started text not null,
  limitations text[] not null default '{}',
  notice_title text,
  notice_body text,
  support_url text,
  privacy_url text,
  icon_path text,
  updated_at timestamptz not null default now(),
  check ((notice_title is null) = (notice_body is null))
);

create table lsicorp.doc_pages (
  id uuid primary key default gen_random_uuid(),
  product_slug text not null references lsicorp.products (slug) on update cascade on delete cascade,
  slug text not null check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  title text not null check (length(trim(title)) > 0),
  summary text not null,
  audience text not null,
  sort_order integer not null default 0,
  body text not null,
  last_reviewed date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'published')),
  updated_at timestamptz not null default now(),
  unique (product_slug, slug)
);

create table lsicorp.faqs (
  id uuid primary key default gen_random_uuid(),
  product_slug text not null references lsicorp.products (slug) on update cascade on delete cascade,
  question text not null check (length(trim(question)) > 0),
  answer text not null,
  category text not null,
  escalation text,
  visible boolean not null default false,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);

-- About and policy pages.
create table lsicorp.pages (
  slug text primary key check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  title text not null check (length(trim(title)) > 0),
  description text not null,
  body text not null,
  last_reviewed date not null default current_date,
  updated_at timestamptz not null default now()
);

create table lsicorp.releases (
  id uuid primary key default gen_random_uuid(),
  product_slug text not null references lsicorp.products (slug) on update cascade on delete restrict,
  platform text not null check (platform in ('android', 'ios', 'web', 'windows', 'macos', 'linux', 'other')),
  version text not null check (version ~ '^[0-9A-Za-z][0-9A-Za-z.-]*$'),
  channel text not null default 'stable' check (channel in ('stable', 'beta', 'preview')),
  status text not null default 'draft'
    check (status in ('draft', 'in-review', 'available', 'superseded', 'withdrawn')),
  release_date date not null,
  destination_type text not null check (destination_type in ('store', 'web-app', 'file')),
  destination_url text not null,
  artifact_filename text,
  artifact_file_type text,
  artifact_size_bytes bigint check (artifact_size_bytes > 0),
  artifact_sha256 text check (artifact_sha256 ~ '^[0-9a-f]{64}$'),
  compat_minimum text not null,
  compat_device_class text not null,
  compat_dependencies text[] not null default '{}',
  steps text[] not null check (cardinality(steps) > 0),
  notes text[] not null check (cardinality(notes) > 0),
  known_issues text[] not null default '{}',
  licence text not null,
  support_route text not null,
  prepared_by uuid references lsicorp.staff (user_id) on delete restrict,
  reviewed_by uuid references lsicorp.staff (user_id) on delete restrict,
  reviewed_at timestamptz,
  superseded_by text,
  withdrawn_reason text,
  updated_at timestamptz not null default now(),
  unique (product_slug, platform, version),
  -- One live release per product, platform and channel. Deferred so that
  -- publishing a new version can supersede the old one in the same transaction.
  constraint one_available_release_per_channel
    exclude using btree (product_slug with =, platform with =, channel with =)
    where (status = 'available') deferrable initially deferred
);

create index releases_product_idx on lsicorp.releases (product_slug, release_date desc);

-- Messages sent through the contact form. Visitors can add one and nothing
-- else; only staff can read them.
create table lsicorp.enquiries (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  name text not null check (length(trim(name)) between 1 and 120),
  email text not null check (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' and length(email) <= 200),
  organisation text check (length(organisation) <= 160),
  service_slug text references lsicorp.services (slug) on update cascade on delete set null,
  message text not null check (length(trim(message)) between 10 and 4000),
  -- The sender agreed to be contacted about this enquiry.
  consent boolean not null check (consent),
  status text not null default 'new' check (status in ('new', 'in-progress', 'closed')),
  notes text
);

create index enquiries_created_idx on lsicorp.enquiries (created_at desc);

-- Who changed what, and when. Rows are written only by the audit trigger.
create table lsicorp.audit_log (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor uuid,
  actor_name text,
  table_name text not null,
  record_key text not null,
  action text not null check (action in ('insert', 'update', 'delete')),
  old_data jsonb,
  new_data jsonb
);

create index audit_log_at_idx on lsicorp.audit_log (at desc);

-- ===== supabase/migrations/20261006000002_rules.sql =====

-- Publishing rules, enforced in the database so that no client can skip them.

create function lsicorp.current_staff_role() returns text
language sql stable security definer set search_path = '' as $$
  select role from lsicorp.staff where user_id = (select auth.uid()) and active
$$;

create function lsicorp.is_staff(roles text[] default array['editor', 'release_manager', 'admin']) returns boolean
language sql stable set search_path = '' as $$
  select coalesce(lsicorp.current_staff_role() = any (roles), false)
$$;

-- Returns what is wrong with a link that leaves the LSI website, or null if it may be published.
create function lsicorp.url_problem(url text, allowed text[]) returns text
language plpgsql immutable set search_path = '' as $$
declare
  host text;
begin
  host := lower(substring(url from '^https://([^/?#@:\s]+)(?::[0-9]+)?(?:[/?#]|$)'));
  if host is null then
    return 'must be an https URL without embedded credentials';
  end if;
  if not (host = any (allowed)) then
    return format('host "%s" is not in the allowed external domains', host);
  end if;
  if url ~* '[?&][^=&#]*(token|secret|signature|key|password|credential|x-amz|x-goog|expires)[^=&#]*=' or url ~* '[?&]sig=' then
    return 'looks like a signed or credentialed private URL';
  end if;
  return null;
end
$$;

create function lsicorp.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end
$$;

create function lsicorp.products_guard() returns trigger
language plpgsql set search_path = '' as $$
declare
  allowed text[];
  link text;
  problem text;
begin
  select allowed_external_domains into allowed from lsicorp.site_settings;
  foreach link in array array[new.support_url, new.privacy_url] loop
    -- A product link is a path on this site or an allowlisted https URL.
    if link is not null and link !~ '^/([^/]|$)' then
      problem := lsicorp.url_problem(link, coalesce(allowed, '{}'));
      if problem is not null then
        raise exception 'Product link %', problem using errcode = 'check_violation';
      end if;
    end if;
  end loop;

  if exists (select 1 from unnest(new.services) s where not exists (select 1 from lsicorp.services where slug = s)) then
    raise exception 'A product can only list services that exist' using errcode = 'check_violation';
  end if;

  if new.status not in ('available', 'maintenance') and exists (
    select 1 from lsicorp.releases r where r.product_slug = new.slug and r.status = 'available'
  ) then
    raise exception 'This product has a published release. Withdraw it before changing the status to "%".', new.status
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;

create function lsicorp.releases_guard() returns trigger
language plpgsql set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  allowed text[];
  problem text;
  product_status text;
  content_changed boolean;
  workflow constant text[] := array['status', 'prepared_by', 'reviewed_by', 'reviewed_at', 'superseded_by', 'withdrawn_reason', 'updated_at'];
begin
  -- 1. Rules about the record itself. These apply to everyone, including seeds.
  select allowed_external_domains into allowed from lsicorp.site_settings;
  problem := lsicorp.url_problem(new.destination_url, coalesce(allowed, '{}'));
  if problem is not null then
    raise exception 'Destination %', problem using errcode = 'check_violation';
  end if;

  if (new.destination_type = 'web-app') <> (new.platform = 'web') then
    raise exception 'The "web" platform and the "web-app" destination type must be used together'
      using errcode = 'check_violation';
  end if;
  if new.destination_type = 'store' and new.platform = 'linux' then
    raise exception 'A store destination is not valid for Linux' using errcode = 'check_violation';
  end if;

  if new.destination_type = 'file' then
    if new.artifact_filename is null or new.artifact_file_type is null
       or new.artifact_size_bytes is null or new.artifact_sha256 is null then
      raise exception 'A direct file needs a filename, file type, size and SHA-256 checksum'
        using errcode = 'check_violation';
    end if;
    if right(split_part(split_part(new.destination_url, '?', 1), '#', 1), length(new.artifact_filename) + 1)
       <> '/' || new.artifact_filename then
      raise exception 'The destination does not end with the artifact filename "%"', new.artifact_filename
        using errcode = 'check_violation';
    end if;
  elsif num_nonnulls(new.artifact_filename, new.artifact_file_type, new.artifact_size_bytes, new.artifact_sha256) > 0 then
    raise exception 'Artifact details only apply to a direct file download' using errcode = 'check_violation';
  end if;

  if (new.status = 'superseded') <> (new.superseded_by is not null) then
    raise exception 'A superseded release, and only a superseded release, names the version that replaced it'
      using errcode = 'check_violation';
  end if;
  if (new.status = 'withdrawn') <> (new.withdrawn_reason is not null) then
    raise exception 'A withdrawn release, and only a withdrawn release, gives a reason'
      using errcode = 'check_violation';
  end if;
  if new.status = 'superseded' and not exists (
    select 1 from lsicorp.releases r
    where r.product_slug = new.product_slug and r.platform = new.platform
      and r.version = new.superseded_by and r.status in ('available', 'superseded', 'withdrawn')
  ) then
    raise exception 'Version "%" is not a published release for this product and platform', new.superseded_by
      using errcode = 'check_violation';
  end if;

  if new.status = 'available' then
    select status into product_status from lsicorp.products where slug = new.product_slug;
    if product_status not in ('available', 'maintenance') then
      raise exception 'The product status is "%". Set it to "available" before publishing a release.', product_status
        using errcode = 'check_violation';
    end if;
  end if;

  -- 2. Workflow rules for signed-in staff. With no user (the seed file, or
  --    maintenance with the service role) the record is taken as given.
  if actor is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'A new release starts as a draft' using errcode = 'check_violation';
    end if;
    new.prepared_by := actor;
    new.reviewed_by := null;
    new.reviewed_at := null;
    return new;
  end if;

  content_changed := (to_jsonb(new) - workflow) is distinct from (to_jsonb(old) - workflow);

  if content_changed then
    if old.status not in ('draft', 'in-review') or new.status not in ('draft', 'in-review') then
      raise exception 'The details of a published release are frozen. Return it to draft to change it, then have it reviewed again.'
        using errcode = 'check_violation';
    end if;
    -- Whoever last changed the details owns them, so cannot also approve them.
    new.prepared_by := actor;
  else
    new.prepared_by := old.prepared_by;
  end if;

  new.reviewed_by := old.reviewed_by;
  new.reviewed_at := old.reviewed_at;

  if new.status is distinct from old.status then
    if (old.status, new.status) not in (
      ('draft', 'in-review'), ('in-review', 'draft'), ('in-review', 'available'),
      ('available', 'superseded'), ('available', 'withdrawn'), ('superseded', 'withdrawn'),
      ('available', 'draft'), ('superseded', 'draft'), ('withdrawn', 'draft')
    ) then
      raise exception 'A release cannot move from "%" to "%"', old.status, new.status
        using errcode = 'check_violation';
    end if;

    if new.status = 'available' then
      if new.prepared_by = actor then
        raise exception 'A release must be approved by a different person from the one who prepared it'
          using errcode = 'check_violation';
      end if;
      new.reviewed_by := actor;
      new.reviewed_at := now();
    elsif new.status in ('draft', 'in-review') then
      new.reviewed_by := null;
      new.reviewed_at := null;
    end if;
  end if;

  return new;
end
$$;

-- Publishing a version supersedes the one it replaces, so there is never a
-- moment with two live downloads or none.
create function lsicorp.releases_supersede_previous() returns trigger
language plpgsql set search_path = '' as $$
begin
  update lsicorp.releases r
  set status = 'superseded', superseded_by = new.version
  where r.product_slug = new.product_slug and r.platform = new.platform and r.channel = new.channel
    and r.status = 'available' and r.id <> new.id;
  return null;
end
$$;

create function lsicorp.audit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  row_data jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  if tg_op = 'UPDATE' and to_jsonb(old) = to_jsonb(new) then
    return null;
  end if;
  insert into lsicorp.audit_log (actor, actor_name, table_name, record_key, action, old_data, new_data)
  values (
    actor,
    (select display_name from lsicorp.staff where user_id = actor),
    tg_table_name,
    case tg_table_name
      when 'releases' then format('%s/%s-%s', row_data ->> 'product_slug', row_data ->> 'platform', row_data ->> 'version')
      when 'doc_pages' then format('%s/%s', row_data ->> 'product_slug', row_data ->> 'slug')
      else coalesce(row_data ->> 'slug', row_data ->> 'user_id', row_data ->> 'id')
    end,
    lower(tg_op),
    case when tg_op <> 'INSERT' then to_jsonb(old) end,
    case when tg_op <> 'DELETE' then to_jsonb(new) end
  );
  return null;
end
$$;

create trigger products_guard before insert or update on lsicorp.products
  for each row execute function lsicorp.products_guard();
create trigger releases_guard before insert or update on lsicorp.releases
  for each row execute function lsicorp.releases_guard();
create trigger releases_supersede_previous after insert or update of status on lsicorp.releases
  for each row when (new.status = 'available') execute function lsicorp.releases_supersede_previous();

do $$
declare
  t text;
begin
  foreach t in array array['site_settings', 'services', 'products', 'doc_pages', 'faqs', 'pages', 'releases'] loop
    execute format('create trigger touch_updated_at before update on lsicorp.%I for each row execute function lsicorp.set_updated_at()', t);
  end loop;
  foreach t in array array['staff', 'site_settings', 'services', 'products', 'doc_pages', 'faqs', 'pages', 'releases'] loop
    execute format('create trigger audit after insert or update or delete on lsicorp.%I for each row execute function lsicorp.audit()', t);
  end loop;
end
$$;

-- ===== supabase/migrations/20261006000003_security.sql =====

-- Row-level security. Visitors read published content with the anon key;
-- staff write according to their role.
--   editor           products, documentation, FAQs and pages
--   release_manager  everything an editor can do, plus releases
--   admin            everything, plus site settings, staff and deletions

alter table lsicorp.staff enable row level security;
alter table lsicorp.site_settings enable row level security;
alter table lsicorp.services enable row level security;
alter table lsicorp.products enable row level security;
alter table lsicorp.enquiries enable row level security;
alter table lsicorp.doc_pages enable row level security;
alter table lsicorp.faqs enable row level security;
alter table lsicorp.pages enable row level security;
alter table lsicorp.releases enable row level security;
alter table lsicorp.audit_log enable row level security;

-- Grants are limited to this schema; nothing outside "lsicorp" is touched.
revoke all on all tables in schema lsicorp from anon, authenticated;
grant usage on schema lsicorp to anon, authenticated, service_role;
grant all on all tables in schema lsicorp to service_role;
grant select on lsicorp.site_settings, lsicorp.services, lsicorp.products, lsicorp.doc_pages, lsicorp.faqs, lsicorp.pages, lsicorp.releases
  to anon, authenticated;
grant select on lsicorp.staff, lsicorp.audit_log, lsicorp.enquiries to authenticated;
grant insert, update, delete on lsicorp.staff, lsicorp.services, lsicorp.products, lsicorp.doc_pages, lsicorp.faqs, lsicorp.pages, lsicorp.releases
  to authenticated;
-- A visitor may send an enquiry, and may set only these columns of it.
grant insert (name, email, organisation, service_slug, message, consent) on lsicorp.enquiries to anon, authenticated;
grant update (status, notes), delete on lsicorp.enquiries to authenticated;
grant update on lsicorp.site_settings to authenticated;
grant execute on function lsicorp.current_staff_role(), lsicorp.is_staff(text[]) to anon, authenticated;

-- Reading
create policy "anyone reads site settings" on lsicorp.site_settings for select using (true);
create policy "anyone reads services" on lsicorp.services for select using (true);
create policy "anyone reads products" on lsicorp.products for select using (true);
create policy "anyone reads pages" on lsicorp.pages for select using (true);
create policy "anyone reads published docs" on lsicorp.doc_pages for select
  using (status = 'published' or (select lsicorp.is_staff()));
create policy "anyone reads visible faqs" on lsicorp.faqs for select
  using (visible or (select lsicorp.is_staff()));
create policy "anyone reads published releases" on lsicorp.releases for select
  using (status in ('available', 'superseded', 'withdrawn') or (select lsicorp.is_staff()));
create policy "staff read staff" on lsicorp.staff for select to authenticated
  using (user_id = (select auth.uid()) or (select lsicorp.is_staff()));
create policy "staff read the audit log" on lsicorp.audit_log for select to authenticated
  using ((select lsicorp.is_staff()));

-- Content: any staff member writes, only an admin deletes.
do $$
declare
  t text;
begin
  foreach t in array array['services', 'products', 'doc_pages', 'faqs', 'pages'] loop
    execute format('create policy "staff insert" on lsicorp.%I for insert to authenticated with check ((select lsicorp.is_staff()))', t);
    execute format('create policy "staff update" on lsicorp.%I for update to authenticated using ((select lsicorp.is_staff())) with check ((select lsicorp.is_staff()))', t);
    execute format('create policy "admins delete" on lsicorp.%I for delete to authenticated using ((select lsicorp.is_staff(array[''admin''])))', t);
  end loop;
end
$$;

-- Releases: release managers and admins. A release that has been published is
-- withdrawn, never deleted, so its record stays auditable.
create policy "release managers insert" on lsicorp.releases for insert to authenticated
  with check ((select lsicorp.is_staff(array['release_manager', 'admin'])));
create policy "release managers update" on lsicorp.releases for update to authenticated
  using ((select lsicorp.is_staff(array['release_manager', 'admin'])))
  with check ((select lsicorp.is_staff(array['release_manager', 'admin'])));
create policy "admins delete drafts" on lsicorp.releases for delete to authenticated
  using (status = 'draft' and (select lsicorp.is_staff(array['admin'])));

-- Enquiries: anyone may send one; only staff may read or handle them.
create policy "anyone sends an enquiry" on lsicorp.enquiries for insert with check (true);
create policy "staff read enquiries" on lsicorp.enquiries for select to authenticated using ((select lsicorp.is_staff()));
create policy "staff handle enquiries" on lsicorp.enquiries for update to authenticated
  using ((select lsicorp.is_staff())) with check ((select lsicorp.is_staff()));
create policy "admins delete enquiries" on lsicorp.enquiries for delete to authenticated
  using ((select lsicorp.is_staff(array['admin'])));

-- Site settings and staff: admins only.
create policy "admins update site settings" on lsicorp.site_settings for update to authenticated
  using ((select lsicorp.is_staff(array['admin']))) with check ((select lsicorp.is_staff(array['admin'])));
create policy "admins insert staff" on lsicorp.staff for insert to authenticated
  with check ((select lsicorp.is_staff(array['admin'])));
create policy "admins update staff" on lsicorp.staff for update to authenticated
  using ((select lsicorp.is_staff(array['admin']))) with check ((select lsicorp.is_staff(array['admin'])));
create policy "admins delete staff" on lsicorp.staff for delete to authenticated
  using ((select lsicorp.is_staff(array['admin'])));

-- ===== supabase/migrations/20261006000004_storage.sql =====

-- Bucket for direct-download release files. Files are publicly readable by
-- URL; only release managers and admins can add or replace them.
-- To serve files from this bucket, add the project's host
-- (<project-ref>.supabase.co) to site_settings.allowed_external_domains.

insert into storage.buckets (id, name, public)
values ('lsicorp-release-files', 'lsicorp-release-files', true)
on conflict (id) do nothing;

create policy "lsicorp: release managers add release files" on storage.objects for insert to authenticated
  with check (bucket_id = 'lsicorp-release-files' and (select lsicorp.is_staff(array['release_manager', 'admin'])));
create policy "lsicorp: release managers replace release files" on storage.objects for update to authenticated
