insert into lsicorp.products (slug, public_name, internal_name, mark, tagline, summary, category, sort_order, status, status_note, audiences, capabilities, requirements, services, platforms, platform_note, getting_started, limitations, notice_title, notice_body, support_url, privacy_url, icon_path)
values ('1145', '1145 Lifestyle', '1145 Lifestyle', '1145', 'Shop, ride and earn in one connected commerce platform.', '1145 is LSI''s flagship: a connected marketplace that brings branded online shopping together with the services needed to complete a transaction, from product discovery and merchant storefronts to delivery, rides and digital financial tools.', 'Commerce', 1, 'available', '1145 Lifestyle is live as a web app at 1145.io. It runs in your browser, so there is nothing to download.', '[{"name":"Consumers","description":"People who want to discover, buy and receive products, and use related services, in one place."},{"name":"Merchants and brand owners","description":"Businesses that want their own storefront, with tools to list products, manage orders and reach customers."},{"name":"Delivery partners and drivers","description":"People who fulfil deliveries and rides through the platform."}]'::jsonb, '[{"name":"Marketplace and brand storefronts","group":"Customer shopping","availability":"available","description":"Browse categories, deals and new arrivals from many sellers, each with their own storefront."},{"name":"Merchant tools","group":"Merchants","availability":"available","description":"Register as a merchant, set up a store, list products, manage stock and orders, and see how the store is performing."},{"name":"Secure checkout and payments","group":"Payments","availability":"available","description":"Pay for an order through an integrated, encrypted checkout."},{"name":"Order tracking and delivery","group":"Logistics","availability":"available","description":"Follow an order from purchase to delivery, with the logistics layer connecting merchants to drivers."},{"name":"Rides","group":"Logistics","availability":"available","description":"Request and manage rides through the same account."},{"name":"Wallet and rewards","group":"Payments","availability":"available","description":"A wallet and rewards connected to activity on the platform. The terms on 1145.io apply to any financial feature."},{"name":"Mobile apps","group":"Platforms","availability":"planned","description":"Android and iOS apps are planned. Until they are released, use the web app in your phone’s browser."},{"name":"Product recommendations","group":"Customer shopping","availability":"planned","description":"AI-assisted recommendations are on the roadmap."},{"name":"More languages and currencies","group":"Platforms","availability":"planned","description":"Multi-language and multi-currency support is on the roadmap."}]'::jsonb, '[{"label":"Device","detail":"Any phone, tablet or computer with a current web browser. The web app adapts to the screen."},{"label":"Account","detail":"A 1145 account, created on 1145.io. This website never asks for your 1145 sign-in or payment details."},{"label":"Connectivity","detail":"An internet connection."}]'::jsonb, array['digital-platforms', 'logistics-technology', 'financial-technology']::text[], array['web']::text[], '1145 is a web app for now. There are no downloadable apps; mobile apps are planned.', 'Open 1145 in your browser and create an account. You can start shopping straight away, or register as a merchant to open a store.', array['There are no mobile apps to download yet. Use the web app in your phone’s browser.', 'Which services are offered can differ by location.', 'Payments, wallet and rewards are governed by the terms published on 1145.io, not by this website.']::text[], null, null, null, null, null)
on conflict (slug) do nothing;

insert into lsicorp.products (slug, public_name, internal_name, mark, tagline, summary, category, sort_order, status, status_note, audiences, capabilities, requirements, services, platforms, platform_note, getting_started, limitations, notice_title, notice_body, support_url, privacy_url, icon_path)
values ('1145hz', '1145Hz Player', 'LSI Player', 'Hz', 'A media player planned around voice-led search and playback.', 'Media player project centred on voice control, playback and a modular media experience. 1145Hz Player is the public name of the project previously referred to as LSI Player.', 'Media', 2, 'in-development', '1145Hz Player is being built. No download has been published yet.', '[{"name":"Listeners and viewers","description":"People who want to play their own audio and video and find it quickly, including by voice."}]'::jsonb, '[{"name":"Voice-led search and playback","availability":"planned","description":"Find and control media by speaking.","platformNote":"Voice features may not be offered on every platform. Each release will state where they work."},{"name":"Playback","availability":"planned","description":"Play audio and video with standard transport controls. Supported formats will be confirmed by engineering before release."},{"name":"Library management","availability":"planned","description":"Add folders of media and browse them as a library."},{"name":"Modular design","availability":"planned","description":"The player is being developed as separate modules so that features can be added over time."}]'::jsonb, '[{"label":"Operating systems","detail":"Not confirmed yet. Supported operating systems will be listed with the first release."},{"label":"Media formats","detail":"Not confirmed yet."},{"label":"Permissions","detail":"Voice control will need microphone access on platforms where it is offered. Access to the folders you add to your library will also be needed."},{"label":"Connectivity","detail":"Not confirmed yet."}]'::jsonb, array['digital-platforms']::text[], '{}'::text[], 'Features can differ between platforms. Voice control is only promised on platforms where a release says it is implemented.', 'There is nothing to install yet. Installation, first-run setup and library setup steps will be published with the first release.', array['No release exists, so nothing described on this page can be used yet.', 'Supported platforms, formats and voice features are not confirmed.']::text[], null, null, null, null, null)
on conflict (slug) do nothing;

insert into lsicorp.products (slug, public_name, internal_name, mark, tagline, summary, category, sort_order, status, status_note, audiences, capabilities, requirements, services, platforms, platform_note, getting_started, limitations, notice_title, notice_body, support_url, privacy_url, icon_path)
values ('gold-digger', 'LSI Gold Digger', 'LSI Gold Digger', 'GD', 'A gold (XAU/USD) research terminal with a risk engine that has the final say.', 'LSI Gold Digger is a desktop research terminal, analysis engine and risk engine for gold (XAU/USD). It brings market data, macro context, news and technical analysis together, explains every signal it produces, and can place trades through a MetaTrader 5 account only after its risk engine approves them.', 'Market research', 4, 'available', 'Version 0.3 for Windows is available as a preview. It starts on simulated data with a paper account, and live-account trading stays locked until you unlock it yourself.', '[{"name":"People researching the gold market","description":"Anyone who wants structured market context and transparent technical analysis to inform their own decisions."},{"name":"Traders testing a disciplined process","description":"People who want to backtest and paper-trade a rules-based approach, with enforced risk limits, before considering a demo or live account."}]'::jsonb, '[{"name":"Market data","group":"Data","availability":"available","description":"Live prices and closed bars from a MetaTrader 5 terminal, or a built-in simulator when no broker is connected. Simulated data is clearly labelled."},{"name":"Technical analysis and market structure","group":"Analysis","availability":"available","description":"Moving averages, RSI, MACD, ATR, Bollinger Bands and ADX, plus swing structure, breaks of structure, support and resistance, regression channels, Double Bollinger Bands and liquidity pools. No value depends on future bars."},{"name":"Market regime and macro view","group":"Analysis","availability":"available","description":"A regime label from strongly bullish to strongly bearish with high-volatility and event-risk overlays, and a rule-based macro score that lists the reason for every point. The macro view needs a free FRED API key."},{"name":"News and economic calendar","group":"Analysis","availability":"available","description":"Gold-relevant news scored by transparent keyword rules, and a weekly economic calendar. High-impact US events trigger a trading blackout."},{"name":"Signals with reasons","group":"Decision support","availability":"available","description":"Five strategies (trend pullback, confluence, ensemble, adaptive and sniper) that output BUY, SELL or WAIT with every condition, reason and risk listed. No AI model produces or edits a score."},{"name":"Champion and Challenger strategies","group":"Decision support","availability":"available","description":"Confluence is the Champion. Ensemble, Adaptive and Sniper are Challengers, limited to paper and demo accounts until an operator promotes one with a typed confirmation. A promotion is refused unless the strategy beats the Champion on results it had not seen; none has earned it so far."},{"name":"Weekly Focus","group":"Decision support","availability":"available","description":"A weekly thesis: bias, key levels, bullish and bearish scenarios, what would invalidate them, and the events to watch."},{"name":"Risk engine","group":"Risk","availability":"available","description":"The final authority on every order: a mandatory stop loss, a minimum reward-to-risk of 1:2, one position at a time, no averaging into a loss, daily and weekly loss limits, and drawdown tiers that reduce risk after losses. Hard ceilings cannot be raised by any setting."},{"name":"Daily profit target","group":"Risk","availability":"available","description":"An optional stopping rule: when the day''s realised gain reaches the target, new entries pause and the app asks whether to keep trading. It cannot make a day reach the target and never changes a risk limit."},{"name":"Paper trading, backtesting and journal","group":"Testing","availability":"available","description":"A paper account, bar-by-bar backtests and walk-forward tests that run through the same signal, risk and execution code as live analysis, and a journal of every proposal, rejection and trade with performance statistics. A backtest can simulate an account you describe (deposit, contract size, minimum lot, leverage, spread and risk rules) and report which strategy fits it."},{"name":"MetaTrader 5 connection and trade execution","group":"Broker connection","availability":"available","description":"Connects to an MT5 account at any broker, including XM. The connection is read-only by default. Sending orders needs three separate opt-ins, and a live account must be unlocked with a typed confirmation every session.","platformNote":"Needs a MetaTrader 5 terminal and Python 3.10 or newer on the same PC, or on another machine you control."},{"name":"AI Gold Analyst","group":"Decision support","availability":"available","description":"A chat assistant that can read the app''s market, signal, macro, news, journal and performance data. It has no ability to place, change or close an order. Needs your own Anthropic API key; usage is billed to you."},{"name":"Macro and news in backtests","group":"Testing","availability":"planned","description":"Backtests are technical-only in this version, because point-in-time macro and news history is not yet included."},{"name":"Signed installer","group":"Distribution","availability":"planned","description":"The installer is not yet code-signed, so Windows shows an unknown-publisher warning."}]'::jsonb, '[{"label":"Operating system","detail":"Windows 10 or 11, 64-bit. No administrator rights are needed to install."},{"label":"To connect a broker","detail":"A MetaTrader 5 terminal (your broker''s download) and Python 3.10 or newer. Not needed to run on simulated data."},{"label":"Optional keys","detail":"A free FRED API key for the macro view, and an Anthropic API key for the AI Gold Analyst. Keys and passwords are stored in Windows Credential Manager, never in files or logs."},{"label":"Connectivity","detail":"An internet connection for live market data, news, the calendar and the optional services."}]'::jsonb, array['market-intelligence']::text[], array['windows']::text[], 'Windows only in this version.', 'Download the installer, check its SHA-256 checksum against the one shown on this site, and run it. The app opens on simulated data with a paper account, so you can explore everything before connecting a broker.', array['The strategies are explainable starting points, not a proven edge. Validation on real broker history is not complete.', 'Backtests are technical-only: macro and news are not included in them.', 'The economic calendar comes from an unofficial public export and can have missing values.', 'News sentiment is based on keyword rules: transparent, but coarse.', 'On a very small account the risk engine will reject almost every trade, because the broker''s minimum position exceeds the permitted risk. That is intended.', 'The installer is not code-signed, so Windows warns that the publisher is unknown.', 'The tool does not provide financial advice.']::text[], 'Trading can lose all the money in the account', 'LSI Gold Digger is a research and analysis tool. Nothing in it is financial advice, no strategy in it is a proven edge, and no result is guaranteed. Past behaviour of a market does not predict its future. Use the paper account and then a demo account before considering real money. You are responsible for your own decisions.', null, null, null)
on conflict (slug) do nothing;

